function drawCharacter_turkey(x,y,hp,fr,cfg,isZeroG) {
    ctx.save();

    // HP bar
    ctx.fillStyle="#111";
    ctx.fillRect(x,y-8,30,5);
    ctx.fillStyle=cfg.color||"#8B4513";
    ctx.fillRect(x,y-8,30*hp,5);

    // Name tag
    if(cfg.name) {
        ctx.fillStyle="#FFF";
        ctx.font="8px Arial";
        ctx.textAlign="center";
        ctx.fillText(cfg.name,x+16,y-12);
    }

    // Body animation - puffing effect
    let puff = Math.sin(fr*0.1)*2;
    let bodyWidth = 18 + puff;
    let bodyHeight = 16 + puff;

    // Main body (turkey brown)
    ctx.fillStyle = cfg.color || "#8B4513";
    ctx.fillRect(x+16-bodyWidth/2, y+8, bodyWidth, bodyHeight);

    // Chest feathers (lighter)
    ctx.fillStyle = "#CD853F";
    ctx.fillRect(x+16-bodyWidth/2+2, y+10, bodyWidth-4, bodyHeight-4);

    // Wing details
    ctx.fillStyle = "#654321";
    ctx.fillRect(x+6, y+12, 6, 8);
    ctx.fillRect(x+20, y+12, 6, 8);

    // Tail feathers (fan-shaped, animated)
    let tailSpread = Math.sin(fr*0.15)*0.3 + 0.7;
    for(let i = 0; i < 5; i++) {
        let angle = (i-2) * 0.4 * tailSpread;
        let tailX = x + 16 + Math.sin(angle) * 8;
        let tailY = y + 20 + Math.cos(angle) * 6;
        ctx.fillStyle = i % 2 === 0 ? "#8B4513" : "#A0522D";
        ctx.fillRect(tailX-1, tailY, 2, 8);
    }

    // Neck
    ctx.fillStyle = "#CD853F";
    ctx.fillRect(x+14, y+4, 4, 6);

    // Head
    ctx.fillStyle = cfg.color || "#8B4513";
    ctx.fillRect(x+12, y, 8, 8);

    // Beak
    ctx.fillStyle = "#FFA500";
    ctx.fillRect(x+11, y+3, 3, 2);

    // Wattle (red dangly thing)
    ctx.fillStyle = "#DC143C";
    ctx.fillRect(x+14, y+5, 2, 3);

    // Golden eyes (commanding gaze)
    ctx.fillStyle = cfg.eyeColor || "#FFD700";
    ctx.fillRect(x+13, y+2, 2, 2);
    ctx.fillRect(x+17, y+2, 2, 2);

    // Eye highlights
    ctx.fillStyle = "#FFFF00";
    ctx.fillRect(x+13, y+2, 1, 1);
    ctx.fillRect(x+17, y+2, 1, 1);

    // Feet
    ctx.fillStyle = "#FFA500";
    ctx.fillRect(x+10, y+24, 3, 4);
    ctx.fillRect(x+19, y+24, 3, 4);

    // Command stripes (military decoration)
    ctx.fillStyle = "#FFD700";
    for(let i = 0; i < 3; i++) {
        ctx.fillRect(x+8, y+14+i*2, 4, 1);
        ctx.fillRect(x+20, y+14+i*2, 4, 1);
    }

    ctx.restore();
}

function drawCharacter_jellyfish(x,y,hp,fr,cfg={},isZeroG=false){
  const bodyCol=cfg.color||'#9966FF';
  const eyeCol=cfg.eyeColor||'#FFDD88';
  ctx.save();
  if(!isZeroG){ctx.fillStyle='rgba(0,0,0,0.15)';ctx.beginPath();ctx.ellipse(x+16,y+30,11,3.5,0,0,Math.PI*2);ctx.fill();}

  // Ethereal glow effect
  const glowIntensity = 0.3 + Math.sin(fr*0.1)*0.2;
  ctx.shadowColor = bodyCol;
  ctx.shadowBlur = 15 * glowIntensity;

  // Bell/dome body with gentle pulsing
  const pulseFactor = 1 + Math.sin(fr*0.08)*0.1;
  ctx.fillStyle = bodyCol;
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.ellipse(x+16, y+12, 14*pulseFactor, 10*pulseFactor, 0, 0, Math.PI*2);
  ctx.fill();

  // Inner glow
  ctx.fillStyle = '#FFFFFF';
  ctx.globalAlpha = 0.3 * glowIntensity;
  ctx.beginPath();
  ctx.ellipse(x+16, y+10, 8*pulseFactor, 6*pulseFactor, 0, 0, Math.PI*2);
  ctx.fill();

  ctx.shadowBlur = 0;
  ctx.globalAlpha = 1;

  // Flowing tentacles with gentle wave motion
  ctx.strokeStyle = bodyCol;
  ctx.lineWidth = 2;
  ctx.globalAlpha = 0.7;
  for(let i=0; i<6; i++){
    const angleOffset = (i/6) * Math.PI * 2;
    const waveOffset = Math.sin(fr*0.12 + i*0.5) * 3;
    ctx.beginPath();
    ctx.moveTo(x+16 + Math.cos(angleOffset)*8, y+20);
    ctx.quadraticCurveTo(x+16 + Math.cos(angleOffset)*6 + waveOffset, y+28, x+16 + Math.cos(angleOffset)*10 + waveOffset*1.5, y+32);
    ctx.stroke();
  }

  ctx.globalAlpha = 1;

  // Gentle pulsing light spots
  const lightPulse = Math.sin(fr*0.15);
  ctx.fillStyle = '#FFFF99';
  ctx.globalAlpha = 0.4 + lightPulse*0.2;
  for(let i=0; i<3; i++){
    const spotX = x + 10 + i*6;
    const spotY = y + 8 + Math.sin(fr*0.1 + i)*2;
    ctx.beginPath();
    ctx.arc(spotX, spotY, 1.5, 0, Math.PI*2);
    ctx.fill();
  }

  ctx.globalAlpha = 1;

  // Wise, gentle eyes
  ctx.fillStyle = eyeCol;
  ctx.beginPath();
  ctx.ellipse(x+12, y+10, 2.5, 3, 0, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x+20, y+10, 2.5, 3, 0, 0, Math.PI*2);
  ctx.fill();

  ctx.fillStyle = '#2A1A4A';
  ctx.beginPath();
  ctx.arc(x+12, y+10, 1.5, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x+20, y+10, 1.5, 0, Math.PI*2);
  ctx.fill();

  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.arc(x+12.5, y+9.5, 0.5, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x+20.5, y+9.5, 0.5, 0, Math.PI*2);
  ctx.fill();

  // HP bar
  ctx.fillStyle='#111';ctx.fillRect(x,y-8,30,5);ctx.fillStyle=cfg.color;ctx.fillRect(x,y-8,30*hp,5);

  // Name tag
  if(cfg.name){ctx.fillStyle='#FFF';ctx.font='8px Arial';ctx.textAlign='center';ctx.fillText(cfg.name,x+16,y-12);}

  ctx.restore();
}

function drawCharacter_wyrm(x,y,hp,fr,cfg={},isZeroG=false){
  const bodyCol=cfg.color||'#4B0082';
  const eyeCol=cfg.eyeColor||'#FFD700';
  ctx.save();
  if(!isZeroG){ctx.fillStyle='rgba(0,0,0,0.3)';ctx.fillRect(x+2,y+52,80,8);}

  // Serpentine body with stellar shimmer
  const segments = 5;
  for(let i = 0; i < segments; i++) {
    const segX = x + (i * 12) - Math.sin((fr + i * 20) * 0.1) * 8;
    const segY = y + 20 + Math.cos((fr + i * 15) * 0.08) * 6;
    const segSize = 15 - (i * 2);

    // Body segment with gradient effect
    const gradient = ctx.createRadialGradient(segX, segY, 0, segX, segY, segSize);
    gradient.addColorStop(0, bodyCol);
    gradient.addColorStop(0.7, '#2E0054');
    gradient.addColorStop(1, '#1A0030');
    ctx.fillStyle = gradient;
    ctx.fillRect(segX - segSize/2, segY - segSize/2, segSize, segSize);

    // Starlight shimmer spots
    if((fr + i * 10) % 60 < 30) {
      ctx.fillStyle = '#FFFFFF';
      ctx.globalAlpha = 0.8;
      ctx.fillRect(segX - 2, segY - 2, 4, 4);
      ctx.globalAlpha = 1;
    }
  }

  // Majestic head
  ctx.fillStyle = bodyCol;
  ctx.fillRect(x - 8, y + 10, 25, 20);

  // Cosmic crown/horns
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(x - 2, y + 8, 4, 8);
  ctx.fillRect(x + 6, y + 8, 4, 8);
  ctx.fillRect(x + 14, y + 8, 4, 8);

  // Galaxy-sized eyes
  ctx.fillStyle = '#000';
  ctx.fillRect(x, y + 15, 6, 6);
  ctx.fillRect(x + 10, y + 15, 6, 6);
  ctx.fillStyle = eyeCol;
  ctx.fillRect(x + 1, y + 16, 4, 4);
  ctx.fillRect(x + 11, y + 16, 4, 4);

  // Cosmic energy aura
  ctx.globalAlpha = 0.3;
  ctx.fillStyle = '#9370DB';
  ctx.fillRect(x - 15, y + 5, 45, 30);
  ctx.globalAlpha = 1;

  // Orbiting debris
  for(let i = 0; i < 3; i++) {
    const orbitX = x + 8 + Math.cos((fr + i * 80) * 0.05) * 25;
    const orbitY = y + 20 + Math.sin((fr + i * 80) * 0.05) * 15;
    ctx.fillStyle = '#888';
    ctx.fillRect(orbitX, orbitY, 2, 2);
  }

  // HP bar
  ctx.fillStyle='#111';
  ctx.fillRect(x,y-8,30,5);
  ctx.fillStyle=cfg.color||bodyCol;
  ctx.fillRect(x,y-8,30*hp,5);

  // Name tag
  if(cfg.name){
    ctx.fillStyle='#FFF';
    ctx.font='8px Arial';
    ctx.fillText(cfg.name,x,y-12);
  }

  ctx.restore();
}

function drawCharacter_spirit(x,y,hp,fr,cfg={},isZeroG=false){
  const bodyCol=cfg.color||'#9966FF';
  const eyeCol=cfg.eyeColor||'#FFFFFF';
  const glowAlpha = 0.3 + 0.2 * Math.sin(fr * 0.1);
  const floatOffset = 3 * Math.sin(fr * 0.08);
  const actualY = y + floatOffset;

  ctx.save();

  // Ethereal glow effect
  ctx.shadowColor = bodyCol;
  ctx.shadowBlur = 15;
  ctx.globalAlpha = glowAlpha;

  // Main ghostly body - wispy bottom
  ctx.fillStyle = bodyCol;
  ctx.beginPath();
  ctx.ellipse(x+15, actualY+15, 12, 14, 0, 0, Math.PI*2);
  ctx.fill();

  // Wispy tail sections
  for(let i = 0; i < 3; i++) {
    const wispY = actualY + 25 + i * 4;
    const wispSize = 8 - i * 2;
    const wispOffset = 2 * Math.sin(fr * 0.12 + i);
    ctx.globalAlpha = glowAlpha - i * 0.1;
    ctx.beginPath();
    ctx.ellipse(x+15 + wispOffset, wispY, wispSize, wispSize * 0.6, 0, 0, Math.PI*2);
    ctx.fill();
  }

  ctx.globalAlpha = 1.0;
  ctx.shadowBlur = 0;

  // Ancient symbol on forehead
  ctx.strokeStyle = '#FFD700';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x+15, actualY+8, 3, 0, Math.PI*2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x+15, actualY+5);
  ctx.lineTo(x+15, actualY+11);
  ctx.moveTo(x+12, actualY+8);
  ctx.lineTo(x+18, actualY+8);
  ctx.stroke();

  // Glowing eyes
  ctx.fillStyle = eyeCol;
  ctx.shadowColor = eyeCol;
  ctx.shadowBlur = 8;
  ctx.beginPath();
  ctx.ellipse(x+11, actualY+12, 2, 3, 0, 0, Math.PI*2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x+19, actualY+12, 2, 3, 0, 0, Math.PI*2);
  ctx.fill();

  ctx.shadowBlur = 0;

  // HP bar
  ctx.fillStyle='#111';
  ctx.fillRect(x,actualY-8,30,5);
  ctx.fillStyle=cfg.color||bodyCol;
  ctx.fillRect(x,actualY-8,30*hp,5);

  // Name tag
  if(cfg.name){
    ctx.fillStyle='#FFF';
    ctx.font='8px monospace';
    ctx.textAlign='center';
    ctx.fillText(cfg.name,x+15,actualY-12);
  }

  ctx.restore();
}

function drawCharacter_spirit(x, y, hp, fr, cfg = {}, isZeroG = false) {
  ctx.save();

  // HP bar
  ctx.fillStyle = '#111';
  ctx.fillRect(x, y - 8, 30, 5);
  ctx.fillStyle = cfg.color || '#7dd3fc';
  ctx.fillRect(x, y - 8, 30 * hp, 5);

  // Name tag
  if (cfg.name) {
    ctx.fillStyle = '#fff';
    ctx.font = '8px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(cfg.name, x + 16, y - 12);
  }

  // Zero-G floating effect
  let floatY = y;
  if (isZeroG) {
    floatY += Math.sin(frame * 0.05 + x * 0.02) * 3;
  }

  // Main ethereal body with cosmic glow
  const glowPulse = 0.3 + Math.sin(frame * 0.08) * 0.2;
  ctx.globalAlpha = glowPulse;

  // Outer glow aura
  const gradient = ctx.createRadialGradient(x + 16, floatY + 16, 0, x + 16, floatY + 16, 20);
  gradient.addColorStop(0, cfg.color || '#7dd3fc');
  gradient.addColorStop(0.5, cfg.color || '#3b82f6');
  gradient.addColorStop(1, 'transparent');
  ctx.fillStyle = gradient;
  ctx.fillRect(x - 4, floatY - 4, 40, 40);

  // Wispy flowing form
  ctx.globalAlpha = 0.7;
  ctx.fillStyle = cfg.color || '#7dd3fc';

  // Central wispy body
  const wispOffset = Math.sin(frame * 0.06) * 2;
  ctx.beginPath();
  ctx.ellipse(x + 16, floatY + 12, 8 + wispOffset, 12, 0, 0, Math.PI * 2);
  ctx.fill();

  // Floating spirit trails
  ctx.globalAlpha = 0.4;
  for (let i = 0; i < 3; i++) {
    const trailX = x + 16 + Math.sin(frame * 0.04 + i) * 6;
    const trailY = floatY + 20 + i * 4;
    ctx.beginPath();
    ctx.ellipse(trailX, trailY, 3, 6, Math.PI * 0.3, 0, Math.PI * 2);
    ctx.fill();
  }

  // Ancient cosmic eyes
  ctx.globalAlpha = 0.9;
  ctx.fillStyle = cfg.eyeColor || '#fbbf24';
  const eyeBob = Math.sin(frame * 0.1) * 1;
  ctx.beginPath();
  ctx.arc(x + 12, floatY + 10 + eyeBob, 2, 0, Math.PI * 2);
  ctx.arc(x + 20, floatY + 10 + eyeBob, 2, 0, Math.PI * 2);
  ctx.fill();

  // Mystical star particles
  ctx.globalAlpha = 0.6;
  ctx.fillStyle = '#fff';
  for (let i = 0; i < 4; i++) {
    const starX = x + 8 + (i * 6) + Math.sin(frame * 0.03 + i) * 3;
    const starY = floatY + 5 + Math.cos(frame * 0.04 + i) * 4;
    ctx.fillRect(starX, starY, 1, 1);
  }

  ctx.restore();
}

function drawCharacter_sockduck(x, y, hp, fr, cfg = {}, isZeroG = false) {
  ctx.save();

  // HP bar
  ctx.fillStyle = '#111';
  ctx.fillRect(x, y - 8, 30, 5);
  ctx.fillStyle = cfg.color || '#4a9eff';
  ctx.fillRect(x, y - 8, 30 * hp, 5);

  // Name tag
  if (cfg.name) {
    ctx.fillStyle = '#fff';
    ctx.font = '8px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(cfg.name, x + 16, y - 12);
  }

  const bobOffset = isZeroG ? Math.sin(frame * 0.1) * 2 : 0;
  const centerX = x + 16;
  const centerY = y + 16 + bobOffset;

  // Duck body (small and compressed)
  ctx.fillStyle = cfg.color || '#4a9eff';
  ctx.beginPath();
  ctx.ellipse(centerX, centerY + 2, 12, 8, 0, 0, Math.PI * 2);
  ctx.fill();

  // Duck head (proportionally small)
  ctx.beginPath();
  ctx.ellipse(centerX, centerY - 6, 8, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  // Bill (tiny)
  ctx.fillStyle = '#ffa500';
  ctx.beginPath();
  ctx.ellipse(centerX - 8, centerY - 6, 3, 2, 0, 0, Math.PI * 2);
  ctx.fill();

  // Eyes (looking confused/cranky)
  ctx.fillStyle = cfg.eyeColor || '#ff4444';
  ctx.beginPath();
  ctx.arc(centerX - 3, centerY - 8, 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(centerX + 3, centerY - 8, 2, 0, Math.PI * 2);
  ctx.fill();

  // Eye pupils (angry/confused expression)
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(centerX - 2, centerY - 7, 1, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(centerX + 4, centerY - 7, 1, 0, Math.PI * 2);
  ctx.fill();

  // Tiny sock pieces around (her snack remnants)
  const sockBits = Math.floor(frame * 0.05) % 4;
  for (let i = 0; i < sockBits; i++) {
    ctx.fillStyle = ['#ff69b4', '#90ee90', '#ffb6c1', '#87ceeb'][i];
    const angle = (frame * 0.02 + i * Math.PI / 2);
    const sockX = centerX + Math.cos(angle) * 18;
    const sockY = centerY + Math.sin(angle) * 15;
    ctx.fillRect(sockX, sockY, 2, 3);
  }

  // Cosmic sparkles (showing her galactic origin despite being shrunk)
  if (frame % 60 < 30) {
    ctx.fillStyle = '#ffff88';
    ctx.beginPath();
    ctx.arc(centerX - 10, centerY - 12, 1, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(centerX + 12, centerY + 8, 1, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.restore();
}
